def RBFCreateSAA_CONTOURSVector(builder, data):
    return builder.CreateVectorOfTables(data)

def CreateSAA_CONTOURSVector(builder, data):
    return RBFCreateSAA_CONTOURSVector(builder, data)

def RBFAddSPACE_WEATHER_REFS(builder, SPACE_WEATHER_REFS):
    builder.PrependUOffsetTRelativeSlot(26, flatbuffers.number_types.UOffsetTFlags.py_type(SPACE_WEATHER_REFS), 0)

def AddSPACE_WEATHER_REFS(builder, SPACE_WEATHER_REFS):
    RBFAddSPACE_WEATHER_REFS(builder, SPACE_WEATHER_REFS)

def RBFStartSPACE_WEATHER_REFSVector(builder, numElems):
    return builder.StartVector(4, numElems, 4)

def StartSPACE_WEATHER_REFSVector(builder, numElems):
    return RBFStartSPACE_WEATHER_REFSVector(builder, numElems)

def RBFCreateSPACE_WEATHER_REFSVector(builder, data):
    return builder.CreateVectorOfTables(data)

def CreateSPACE_WEATHER_REFSVector(builder, data):
    return RBFCreateSPACE_WEATHER_REFSVector(builder, data)

def RBFAddPROVENANCE(builder, PROVENANCE):
    builder.PrependUOffsetTRelativeSlot(27, flatbuffers.number_types.UOffsetTFlags.py_type(PROVENANCE), 0)

def AddPROVENANCE(builder, PROVENANCE):
    RBFAddPROVENANCE(builder, PROVENANCE)

def RBFEnd(builder):
    return builder.EndObject()

def End(builder):
    return RBFEnd(builder)

import PVN
import RBFSaaContour
import RBFStructureFeature
try:
    from typing import List, Optional
except:
    pass

class RBFT(object):

    # RBFT
    def __init__(
        self,
        RBF_ID = None,
        BODY_NAME = None,
        BODY_NAIF_ID = 0,
        MODEL = 0,
        MODEL_VERSION = None,
        MAG_MODEL_ID = None,
        REFERENCE_FRAME = None,
        SPECIES = 0,
        FLUX_TYPE = 0,
        UNITS = None,
        EPOCH = None,
        KP = 0.0,
        HAS_KP = False,
        DST_NT = 0.0,
        HAS_DST_NT = False,
        F107 = 0.0,
        HAS_F107 = False,
        SOLAR_WIND_PRESSURE_NPA = 0.0,
        HAS_SOLAR_WIND_PRESSURE = False,
        QUANTILE_PCT = 50.0,
        L_SHELLS = None,
        ENERGY_MEV = None,
        B_OVER_B0 = None,
        FLUX_GRID = None,
        STRUCTURES = None,
        SAA_CONTOURS = None,
        SPACE_WEATHER_REFS = None,
        PROVENANCE = None,
    ):
        self.RBF_ID = RBF_ID  # type: Optional[str]
        self.BODY_NAME = BODY_NAME  # type: Optional[str]
        self.BODY_NAIF_ID = BODY_NAIF_ID  # type: int
        self.MODEL = MODEL  # type: int
        self.MODEL_VERSION = MODEL_VERSION  # type: Optional[str]
        self.MAG_MODEL_ID = MAG_MODEL_ID  # type: Optional[str]
        self.REFERENCE_FRAME = REFERENCE_FRAME  # type: Optional[str]
        self.SPECIES = SPECIES  # type: int
        self.FLUX_TYPE = FLUX_TYPE  # type: int
        self.UNITS = UNITS  # type: Optional[str]
        self.EPOCH = EPOCH  # type: Optional[str]
        self.KP = KP  # type: float
        self.HAS_KP = HAS_KP  # type: bool
        self.DST_NT = DST_NT  # type: float
        self.HAS_DST_NT = HAS_DST_NT  # type: bool
        self.F107 = F107  # type: float
        self.HAS_F107 = HAS_F107  # type: bool
        self.SOLAR_WIND_PRESSURE_NPA = SOLAR_WIND_PRESSURE_NPA  # type: float
        self.HAS_SOLAR_WIND_PRESSURE = HAS_SOLAR_WIND_PRESSURE  # type: bool
        self.QUANTILE_PCT = QUANTILE_PCT  # type: float
        self.L_SHELLS = L_SHELLS  # type: Optional[List[float]]
        self.ENERGY_MEV = ENERGY_MEV  # type: Optional[List[float]]
        self.B_OVER_B0 = B_OVER_B0  # type: Optional[List[float]]
        self.FLUX_GRID = FLUX_GRID  # type: Optional[List[float]]
        self.STRUCTURES = STRUCTURES  # type: Optional[List[RBFStructureFeature.RBFStructureFeatureT]]
        self.SAA_CONTOURS = SAA_CONTOURS  # type: Optional[List[RBFSaaContour.RBFSaaContourT]]
        self.SPACE_WEATHER_REFS = SPACE_WEATHER_REFS  # type: Optional[List[Optional[str]]]
        self.PROVENANCE = PROVENANCE  # type: Optional[PVN.PVNT]

    @classmethod
    def InitFromBuf(cls, buf, pos):
        tmpRbf = RBF()
        tmpRbf.Init(buf, pos)
        return cls.InitFromObj(tmpRbf)

    @classmethod
    def InitFromPackedBuf(cls, buf, pos=0):
        n = flatbuffers.encode.Get(flatbuffers.packer.uoffset, buf, pos)
        return cls.InitFromBuf(buf, pos+n)

    @classmethod
    def InitFromObj(cls, tmpRbf):
        x = RBFT()
        x._UnPack(tmpRbf)
        return x

    # RBFT
    def _UnPack(self, RBF):
        if RBF is None:
            return
        self.RBF_ID = RBF.RBF_ID()
        self.BODY_NAME = RBF.BODY_NAME()
        self.BODY_NAIF_ID = RBF.BODY_NAIF_ID()
        self.MODEL = RBF.MODEL()
        self.MODEL_VERSION = RBF.MODEL_VERSION()
        self.MAG_MODEL_ID = RBF.MAG_MODEL_ID()
        self.REFERENCE_FRAME = RBF.REFERENCE_FRAME()
        self.SPECIES = RBF.SPECIES()
        self.FLUX_TYPE = RBF.FLUX_TYPE()
        self.UNITS = RBF.UNITS()
        self.EPOCH = RBF.EPOCH()
        self.KP = RBF.KP()
        self.HAS_KP = RBF.HAS_KP()
        self.DST_NT = RBF.DST_NT()
        self.HAS_DST_NT = RBF.HAS_DST_NT()
        self.F107 = RBF.F107()
        self.HAS_F107 = RBF.HAS_F107()
        self.SOLAR_WIND_PRESSURE_NPA = RBF.SOLAR_WIND_PRESSURE_NPA()
        self.HAS_SOLAR_WIND_PRESSURE = RBF.HAS_SOLAR_WIND_PRESSURE()
        self.QUANTILE_PCT = RBF.QUANTILE_PCT()
        if not RBF.L_SHELLSIsNone():
            if np is None:
                self.L_SHELLS = []
                for i in range(RBF.L_SHELLSLength()):
                    self.L_SHELLS.append(RBF.L_SHELLS(i))
            else:
                self.L_SHELLS = RBF.L_SHELLSAsNumpy()
        if not RBF.ENERGY_MEVIsNone():
            if np is None:
                self.ENERGY_MEV = []
                for i in range(RBF.ENERGY_MEVLength()):
                    self.ENERGY_MEV.append(RBF.ENERGY_MEV(i))
            else:
                self.ENERGY_MEV = RBF.ENERGY_MEVAsNumpy()
        if not RBF.B_OVER_B0IsNone():
            if np is None:
                self.B_OVER_B0 = []
                for i in range(RBF.B_OVER_B0Length()):
                    self.B_OVER_B0.append(RBF.B_OVER_B0(i))
            else:
                self.B_OVER_B0 = RBF.B_OVER_B0AsNumpy()
        if not RBF.FLUX_GRIDIsNone():
            if np is None:
                self.FLUX_GRID = []
                for i in range(RBF.FLUX_GRIDLength()):
                    self.FLUX_GRID.append(RBF.FLUX_GRID(i))
            else:
                self.FLUX_GRID = RBF.FLUX_GRIDAsNumpy()
        if not RBF.STRUCTURESIsNone():
            self.STRUCTURES = []
            for i in range(RBF.STRUCTURESLength()):
                if RBF.STRUCTURES(i) is None:
                    self.STRUCTURES.append(None)
                else:
                    rBFStructureFeature_ = RBFStructureFeature.RBFStructureFeatureT.InitFromObj(RBF.STRUCTURES(i))
                    self.STRUCTURES.append(rBFStructureFeature_)
        if not RBF.SAA_CONTOURSIsNone():
            self.SAA_CONTOURS = []
            for i in range(RBF.SAA_CONTOURSLength()):
                if RBF.SAA_CONTOURS(i) is None:
                    self.SAA_CONTOURS.append(None)
                else:
                    rBFSaaContour_ = RBFSaaContour.RBFSaaContourT.InitFromObj(RBF.SAA_CONTOURS(i))
                    self.SAA_CONTOURS.append(rBFSaaContour_)
        if not RBF.SPACE_WEATHER_REFSIsNone():
            self.SPACE_WEATHER_REFS = []
            for i in range(RBF.SPACE_WEATHER_REFSLength()):
                self.SPACE_WEATHER_REFS.append(RBF.SPACE_WEATHER_REFS(i))
        if RBF.PROVENANCE() is not None:
            self.PROVENANCE = PVN.PVNT.InitFromObj(RBF.PROVENANCE())

    # RBFT
    def Pack(self, builder):
        if self.RBF_ID is not None:
            RBF_ID = builder.CreateString(self.RBF_ID)
        if self.BODY_NAME is not None:
            BODY_NAME = builder.CreateString(self.BODY_NAME)
        if self.MODEL_VERSION is not None:
            MODEL_VERSION = builder.CreateString(self.MODEL_VERSION)
        if self.MAG_MODEL_ID is not None:
            MAG_MODEL_ID = builder.CreateString(self.MAG_MODEL_ID)
        if self.REFERENCE_FRAME is not None:
            REFERENCE_FRAME = builder.CreateString(self.REFERENCE_FRAME)
        if self.UNITS is not None:
            UNITS = builder.CreateString(self.UNITS)
        if self.EPOCH is not None:
            EPOCH = builder.CreateString(self.EPOCH)
        if self.L_SHELLS is not None:
            if np is not None and type(self.L_SHELLS) is np.ndarray:
                L_SHELLS = builder.CreateNumpyVector(self.L_SHELLS)
            else:
                RBFStartL_SHELLSVector(builder, len(self.L_SHELLS))
                for i in reversed(range(len(self.L_SHELLS))):
                    builder.PrependFloat64(self.L_SHELLS[i])
                L_SHELLS = builder.EndVector()
        if self.ENERGY_MEV is not None:
            if np is not None and type(self.ENERGY_MEV) is np.ndarray:
                ENERGY_MEV = builder.CreateNumpyVector(self.ENERGY_MEV)
            else:
                RBFStartENERGY_MEVVector(builder, len(self.ENERGY_MEV))
                for i in reversed(range(len(self.ENERGY_MEV))):
                    builder.PrependFloat64(self.ENERGY_MEV[i])
                ENERGY_MEV = builder.EndVector()
        if self.B_OVER_B0 is not None:
            if np is not None and type(self.B_OVER_B0) is np.ndarray:
                B_OVER_B0 = builder.CreateNumpyVector(self.B_OVER_B0)
            else:
                RBFStartB_OVER_B0Vector(builder, len(self.B_OVER_B0))
                for i in reversed(range(len(self.B_OVER_B0))):
                    builder.PrependFloat64(self.B_OVER_B0[i])
                B_OVER_B0 = builder.EndVector()
        if self.FLUX_GRID is not None:
            if np is not None and type(self.FLUX_GRID) is np.ndarray:
                FLUX_GRID = builder.CreateNumpyVector(self.FLUX_GRID)
            else:
                RBFStartFLUX_GRIDVector(builder, len(self.FLUX_GRID))
                for i in reversed(range(len(self.FLUX_GRID))):
                    builder.PrependFloat64(self.FLUX_GRID[i])
                FLUX_GRID = builder.EndVector()
        if self.STRUCTURES is not None:
            STRUCTURESlist = []
            for i in range(len(self.STRUCTURES)):
                STRUCTURESlist.append(self.STRUCTURES[i].Pack(builder))
            RBFStartSTRUCTURESVector(builder, len(self.STRUCTURES))
            for i in reversed(range(len(self.STRUCTURES))):
                builder.PrependUOffsetTRelative(STRUCTURESlist[i])
            STRUCTURES = builder.EndVector()
        if self.SAA_CONTOURS is not None:
            SAA_CONTOURSlist = []
            for i in range(len(self.SAA_CONTOURS)):
                SAA_CONTOURSlist.append(self.SAA_CONTOURS[i].Pack(builder))
            RBFStartSAA_CONTOURSVector(builder, len(self.SAA_CONTOURS))
            for i in reversed(range(len(self.SAA_CONTOURS))):
                builder.PrependUOffsetTRelative(SAA_CONTOURSlist[i])
            SAA_CONTOURS = builder.EndVector()
        if self.SPACE_WEATHER_REFS is not None:
            SPACE_WEATHER_REFSlist = []
            for i in range(len(self.SPACE_WEATHER_REFS)):
                SPACE_WEATHER_REFSlist.append(builder.CreateString(self.SPACE_WEATHER_REFS[i]))
            RBFStartSPACE_WEATHER_REFSVector(builder, len(self.SPACE_WEATHER_REFS))
            for i in reversed(range(len(self.SPACE_WEATHER_REFS))):
                builder.PrependUOffsetTRelative(SPACE_WEATHER_REFSlist[i])
            SPACE_WEATHER_REFS = builder.EndVector()
        if self.PROVENANCE is not None:
            PROVENANCE = self.PROVENANCE.Pack(builder)
        RBFStart(builder)
        if self.RBF_ID is not None:
            RBFAddRBF_ID(builder, RBF_ID)
        if self.BODY_NAME is not None:
            RBFAddBODY_NAME(builder, BODY_NAME)
        RBFAddBODY_NAIF_ID(builder, self.BODY_NAIF_ID)
        RBFAddMODEL(builder, self.MODEL)
        if self.MODEL_VERSION is not None:
            RBFAddMODEL_VERSION(builder, MODEL_VERSION)
        if self.MAG_MODEL_ID is not None:
            RBFAddMAG_MODEL_ID(builder, MAG_MODEL_ID)
        if self.REFERENCE_FRAME is not None:
            RBFAddREFERENCE_FRAME(builder, REFERENCE_FRAME)
        RBFAddSPECIES(builder, self.SPECIES)
        RBFAddFLUX_TYPE(builder, self.FLUX_TYPE)
        if self.UNITS is not None:
            RBFAddUNITS(builder, UNITS)
        if self.EPOCH is not None:
            RBFAddEPOCH(builder, EPOCH)
        RBFAddKP(builder, self.KP)
        RBFAddHAS_KP(builder, self.HAS_KP)
        RBFAddDST_NT(builder, self.DST_NT)
        RBFAddHAS_DST_NT(builder, self.HAS_DST_NT)
        RBFAddF107(builder, self.F107)
        RBFAddHAS_F107(builder, self.HAS_F107)
        RBFAddSOLAR_WIND_PRESSURE_NPA(builder, self.SOLAR_WIND_PRESSURE_NPA)
        RBFAddHAS_SOLAR_WIND_PRESSURE(builder, self.HAS_SOLAR_WIND_PRESSURE)
        RBFAddQUANTILE_PCT(builder, self.QUANTILE_PCT)
        if self.L_SHELLS is not None:
            RBFAddL_SHELLS(builder, L_SHELLS)
        if self.ENERGY_MEV is not None:
            RBFAddENERGY_MEV(builder, ENERGY_MEV)
        if self.B_OVER_B0 is not None:
            RBFAddB_OVER_B0(builder, B_OVER_B0)
        if self.FLUX_GRID is not None:
            RBFAddFLUX_GRID(builder, FLUX_GRID)
        if self.STRUCTURES is not None:
            RBFAddSTRUCTURES(builder, STRUCTURES)
        if self.SAA_CONTOURS is not None:
            RBFAddSAA_CONTOURS(builder, SAA_CONTOURS)
        if self.SPACE_WEATHER_REFS is not None:
            RBFAddSPACE_WEATHER_REFS(builder, SPACE_WEATHER_REFS)
        if self.PROVENANCE is not None:
            RBFAddPROVENANCE(builder, PROVENANCE)
        RBF = RBFEnd(builder)
        return RBF
